83	## Pager Configuration
84	
85	```kotlin
86	class ArticleRepository(private val api: ArticleApi) {
87	
88	    fun getArticlesPager(query: String): Flow<PagingData<Article>> {
89	        return Pager(
90	            config = PagingConfig(
91	                pageSize = 20,
92	                prefetchDistance = 5,
93	                enablePlaceholders = false,
94	                initialLoadSize = 40,  // first load is usually 2x pageSize
95	                maxSize = 200          // cap cached pages
96	            ),
97	            pagingSourceFactory = { ArticlePagingSource(api, query) }
98	        ).flow
99	    }
100	}
